$ErrorActionPreference="Stop"
if($env:ALTIORA_PATCH -ne "1"){ throw "ALTIORA_PATCH=1 requis (utiliser tools\patch_runner.ps1)" }

$pyPath = Join-Path (Get-Location).Path "tools\generate_license.py"
$marker = "ABP_LICENSE_GEN_V4"

if(-not (Test-Path -LiteralPath $pyPath)){
  throw "FAIL-CLOSED: tools\generate_license.py introuvable."
}

$existing = Get-Content -LiteralPath $pyPath -Encoding UTF8 -Raw
if($existing -notmatch $marker){
  throw "FAIL-CLOSED: marker V4 absent dans tools\generate_license.py (refuse rewrite)."
}

$b64 = ""
$fixed = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))

Set-Content -LiteralPath $pyPath -Value $fixed -Encoding UTF8
Write-Host "OK: tools\generate_license.py fixed for Ed25519 (V4)."
